function openFreeDice(){modal({kicker:'Free Dice Roller',title:'Roll any dice',html:`<p>This is the manual roller. AI-required rolls use the smaller automatic roll window.</p><div class="diceWorkbench"><input id="diceExpr" class="field" value="1d20" placeholder="2d6+4"><select id="diceMode" class="field"><option value="normal">Normal</option><option value="advantage">Advantage d20</option><option value="disadvantage">Disadvantage d20</option></select><button id="freeRollGo" class="goldBtn">Roll</button></div><div id="freeDiceResult"></div><div id="freeDiceText" class="statusLine"></div>`,buttons:[{label:'Close',onClick:closeModal}]});$('#freeRollGo').onclick=()=>{try{const expr=$('#diceExpr').value.trim(),mode=$('#diceMode').value;let r;if(mode!=='normal'){const mod=/^1d20([+-]\d+)?$/i.exec(expr);if(!mod)throw new Error('Advantage/disadvantage mode uses 1d20 with an optional modifier.');r=Dice().rollD20(mode,{modifier:Number(mod[1]||0),label:'Free Roll'});}else r=Dice().roll(expr,{label:'Free Roll'});state.lastRoll=r;Dice().render($('#freeDiceResult'),r);$('#freeDiceText').textContent=Dice().text(r);}catch(err){$('#freeDiceText').textContent=err.message;}};}
