function defaultProfile(){return {identity:{name:'Adventurer',class:'Fighter',subclass:'',level:1,rulesEdition:'D&D 5e 2024 revised'},abilities:{strength:{score:10,mod:0},dexterity:{score:10,mod:0},constitution:{score:10,mod:0},intelligence:{score:10,mod:0},wisdom:{score:10,mod:0},charisma:{score:10,mod:0}},defenses:{armorClass:10,currentHp:10,maxHp:10,speed:30,conditions:[],exhaustion:0},classFeatures:[],equipment:{weapons:[],armor:[],consumables:[],gear:[]},spellcasting:{canCastSpells:false,cantrips:[],knownSpells:[],preparedSpells:[],slots:{}},magicItems:[]};}
function openCharacterEditor(prefill=profile()){const p=JSON.parse(JSON.stringify(Object.keys(prefill||{}).length?prefill:defaultProfile())),id=p.identity||{},d=p.defenses||{},a=p.abilities||{},score=k=>a[k]?.score??10;modal({kicker:'Character Builder · 2024',title:'Create or edit character',html:`<div class="formGrid"><div class="grid2"><label class="fieldLabel">Name<input id="chName" value="${esc(id.name||charName())}"></label><label class="fieldLabel">Class<input id="chClass" value="${esc(id.class||'')}"></label><label class="fieldLabel">Subclass<input id="chSubclass" value="${esc(id.subclass||'')}"></label><label class="fieldLabel">Level<input id="chLevel" type="number" min="1" max="20" value="${esc(id.level||1)}"></label><label class="fieldLabel">Current HP<input id="chHp" type="number" value="${esc(state.character?.hp??d.currentHp??10)}"></label><label class="fieldLabel">Max HP<input id="chMaxHp" type="number" value="${esc(state.character?.max_hp??d.maxHp??10)}"></label><label class="fieldLabel">AC<input id="chAc" type="number" value="${esc(state.character?.ac??d.armorClass??10)}"></label><label class="fieldLabel">Speed<input id="chSpeed" type="number" value="${esc(d.speed??30)}"></label></div><div class="grid2">${['strength','dexterity','constitution','intelligence','wisdom','charisma'].map(k=>`<label class="fieldLabel">${k.slice(0,3).toUpperCase()}<input data-ability="${k}" type="number" min="1" max="30" value="${score(k)}"></label>`).join('')}</div><label class="fieldLabel">Weapons, one per line (Name | attack bonus | damage)<textarea id="chWeapons" rows="4">${esc((p.equipment?.weapons||[]).map(w=>`${w.name} | ${w.attackBonus??''} | ${w.damage??''}`).join('\n'))}</textarea></label><label class="fieldLabel">Features, one per line<textarea id="chFeatures" rows="4">${esc((p.classFeatures||[]).map(f=>f.name).join('\n'))}</textarea></label><label class="toggleRow"><span>This character can cast spells</span><input id="chCaster" type="checkbox" ${p.spellcasting?.canCastSpells?'checked':''}></label></div>`,buttons:[{label:'Cancel',onClick:closeModal},{label:'Save Character',className:'goldBtn',onClick:async()=>{const abilities={};$$('[data-ability]').forEach(i=>{const n=Number(i.value)||10;abilities[i.dataset.ability]={score:n,mod:Math.floor((n-10)/2)};});const hp=Number($('#chHp').value)||1,maxHp=Number($('#chMaxHp').value)||hp,ac=Number($('#chAc').value)||10,profileOut={...p,identity:{...id,name:$('#chName').value.trim(),class:$('#chClass').value.trim(),subclass:$('#chSubclass').value.trim(),level:Number($('#chLevel').value)||1,rulesEdition:'D&D 5e 2024 revised'},abilities,defenses:{...d,currentHp:hp,maxHp,armorClass:ac,speed:Number($('#chSpeed').value)||30},classFeatures:$('#chFeatures').value.split('\n').map(s=>s.trim()).filter(Boolean).map(name=>({name})),equipment:{...(p.equipment||{}),weapons:$('#chWeapons').value.split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{const [name,attack,damage]=line.split('|').map(x=>x.trim());return{name,attackBonus:Number(attack)||0,damage};})},spellcasting:{...(p.spellcasting||{}),canCastSpells:$('#chCaster').checked}};state.character=await DB().saveCharacter(state.campaign.id,{id:state.character?.id,name:profileOut.identity.name,display_name:profileOut.identity.name,source:'manual',profile:profileOut,hp,max_hp:maxHp,ac});closeModal();renderAll();toast('Character saved as the authoritative record.','ok');}}]});}
function openCombatSetup(){if(!owner())return;modal({kicker:'Combat',title:'Start Initiative Blocks',html:`<p>Players roll their own initiative in the app. Enter enemies below, one per line as <strong>Name | initiative</strong>.</p><label class="fieldLabel">Enemies<textarea id="enemyInit" rows="6" placeholder="Skeleton | 14\nWight | 11"></textarea></label>`,buttons:[{label:'Cancel',onClick:closeModal},{label:'Open Initiative',className:'goldBtn',onClick:async()=>{const enemies=$('#enemyInit').value.split('\n').map(s=>s.trim()).filter(Boolean).map((line,i)=>{const [name,val]=line.split('|').map(x=>x.trim());return{combatant_key:`enemy:${crypto.randomUUID()}`,side:'enemy',display_name:name||`Enemy ${i+1}`,initiative:Number(val)||Dice().secureDie(20),state:{}};});try{await DB().client.from('initiative_entries').delete().eq('campaign_id',state.campaign.id);if(enemies.length)await DB().client.from('initiative_entries').insert(enemies.map(e=>({...e,campaign_id:state.campaign.id})));await DB().saveCampaign(state.campaign.id,{state:{...(state.campaign.state||{}),combatSetup:true},active_block:null,round_number:0,active_deadline:null});closeModal();await refreshAll();renderAll();toast('Combat opened. Players can now roll initiative.','ok');}catch(err){toast(err.message,'bad');}}},{label:'Finalize Blocks',className:'ghostBtn',onClick:async()=>{try{await DB().client.rpc('assign_initiative_blocks',{p_campaign:state.campaign.id});await DB().saveCampaign(state.campaign.id,{active_block:'player_1',round_number:1,active_deadline:new Date(Date.now()+6*3600000).toISOString(),deadline_type:'combat_block',state:{...(state.campaign.state||{}),combatSetup:false}});closeModal();await refreshAll();renderAll();localNotify('turn','The first player initiative block is open.');}catch(err){toast(err.message,'bad');}}}]});}
async function rollMyInitiative(){const p=profile(),mod=Number(p.defenses?.initiativeBonus??p.abilities?.dexterity?.mod??0),adv=Boolean(p.subclassFeatures?.some(f=>f.initiativeAdvantage)),r=Dice().rollD20(adv?'advantage':'normal',{modifier:mod,label:'Initiative'});openRollDisplay(r);try{const row={campaign_id:state.campaign.id,combatant_key:`player:${state.user.id}`,side:'player',user_id:state.user.id,token_id:state.tokens.find(t=>t.owner_user_id===state.user.id)?.id||null,display_name:charName(),initiative:r.total,state:{verified_roll_id:r.id}};await DB().client.from('initiative_entries').upsert(row,{onConflict:'campaign_id,combatant_key'});toast('Initiative submitted.','ok');scheduleRefresh();}catch(err){toast(err.message,'bad');}}
function openRollDisplay(r){modal({kicker:'Dice Result',title:r.label,html:'<div id="standaloneRoll"></div><div class="statusLine" id="standaloneRollText"></div>',buttons:[{label:'Close',onClick:closeModal}]});Dice().render($('#standaloneRoll'),r);$('#standaloneRollText').textContent=Dice().text(r);}
async function advanceBlock(){if(!owner()||blockAdvancePending)return;const previous=state.campaign,c=previous,seq=['player_1','enemy_1','player_2','enemy_2'];let i=seq.indexOf(c.active_block);if(i<0)i=0;const next=seq[(i+1)%4],round=next==='player_1'?(c.round_number||1)+1:(c.round_number||1),deadline=next.startsWith('player')?new Date(Date.now()+6*3600000).toISOString():new Date(Date.now()+5*60000).toISOString(),patch={active_block:next,round_number:round,active_deadline:deadline,deadline_type:next.startsWith('player')?'combat_block':'enemy_resolution'},btn=$('#advanceBlockBtn');blockAdvancePending=true;state.campaign={...c,...patch};renderTimer();renderTurnStatus();renderInitiative();if(btn){btn.disabled=true;btn.textContent='Advanced';}try{const saved=await DB().saveCampaign(c.id,patch);state.campaign={...state.campaign,...saved};renderTimer();renderTurnStatus();renderInitiative();if(next.startsWith('enemy'))void askAI(`Resolve ${BLOCK_NAMES[next]} automatically using the current initiative, battlefield, rules, and available enemy actions. Do not roll for players.`,{responseVisibility:'party',background:true});else localNotify('turn',`${BLOCK_NAMES[next]} is now open for 6 hours.`);scheduleRefresh();}catch(err){state.campaign=previous;renderTimer();renderTurnStatus();renderInitiative();toast(err.message,'bad');}finally{blockAdvancePending=false;if(btn){btn.disabled=false;btn.textContent='Advance Block';}}}
async function submitTurnPrompt(){const idx=BLOCK_INDEX[state.campaign?.active_block],mine=myInitiative();if(!idx||!state.campaign.active_block?.startsWith('player')||!mine||Number(mine.block_index)!==idx){toast('It is not your initiative block yet.','warn');return;}modal({kicker:'Combat Turn',title:'Submit your action',html:`<label class="fieldLabel">Planned action<textarea id="turnAction" rows="5" placeholder="Describe your action, target, movement, and any fallback condition."></textarea></label><p>If the action needs a player-facing roll, the AI DM will open the exact roll automatically.</p>`,buttons:[{label:'Cancel',onClick:closeModal},{label:'Submit',className:'goldBtn',onClick:async()=>{const text=$('#turnAction').value.trim();if(!text)return;await DB().submitTurn(state.campaign.id,state.campaign.round_number,idx,{text,status:'submitted'});closeModal();await askAI(`Combat turn submission for my current initiative block: ${text}`,{responseVisibility:'party'});}}]});}
async function togglePause(){if(!owner())return;const paused=!state.campaign.paused;await DB().saveCampaign(state.campaign.id,{paused,state:{...(state.campaign.state||{}),pauseSnapshot:paused?{active_deadline:state.campaign.active_deadline,paused_at:new Date().toISOString()}:state.campaign.state?.pauseSnapshot}});if(!paused&&state.campaign.state?.pauseSnapshot?.active_deadline){const snap=state.campaign.state.pauseSnapshot,remaining=Math.max(0,new Date(snap.active_deadline)-new Date(snap.paused_at));await DB().saveCampaign(state.campaign.id,{active_deadline:new Date(Date.now()+remaining).toISOString()});}await DB().addStory(state.campaign.id,paused?'campaign_paused':'campaign_resumed',{summary:paused?'Campaign paused by owner.':'Campaign resumed by owner.'});scheduleRefresh();}
async function rewindLastEvent(){if(!owner())return;const evt=state.story.find(e=>e.payload?.state_before);if(!evt){toast('No reversible snapshot is available yet. Use Correct State for recovery.','warn');return;}if(!confirm('Restore the most recent reversible campaign snapshot?'))return;await DB().saveCampaign(state.campaign.id,{state:evt.payload.state_before,current_scene:evt.payload.state_before.sceneText||state.campaign.current_scene});await DB().addStory(state.campaign.id,'owner_rewind',{summary:'Campaign owner restored a previous state snapshot.',source_event:evt.id});scheduleRefresh();}
function correctCampaignState(){if(!owner())return;modal({kicker:'Owner Recovery',title:'Correct campaign state',html:`<label class="fieldLabel">Current scene<textarea id="correctScene" rows="6">${esc(state.campaign.current_scene||'')}</textarea></label><label class="fieldLabel">Round number<input id="correctRound" type="number" min="0" value="${esc(state.campaign.round_number||0)}"></label>`,buttons:[{label:'Cancel',onClick:closeModal},{label:'Apply Correction',className:'dangerBtn',onClick:async()=>{if(!confirm('Apply this owner correction? The correction will be logged.'))return;const before=state.campaign.state||{},scene=$('#correctScene').value,round=Number($('#correctRound').value)||0;await DB().saveCampaign(state.campaign.id,{current_scene:scene,round_number:round,state:{...before,sceneText:scene}});await DB().addStory(state.campaign.id,'owner_correction',{summary:'Campaign state corrected by owner.',state_before:before});closeModal();scheduleRefresh();}}]});}
function openCampaignSwitcher(){showLobby(false);}
document.addEventListener('DOMContentLoaded',init);
